@startuml

class AlphaInsurance {}

class Customer {
  + Name : string
}

class Broker {
  + BrokerId : int
}

class Policy {
  + Type : string
}

class Offer {
  + OfferId : int
  + Status : string
}

class Contract {
  + ContractId : int
  + Price : float
  + Frequency : string
}

class Invoice {
  + InvoiceId : int
  + Amount : float
}

class ClaimCase {
  + CaseId : int
  + Status : string
}

class Estimator {
  + Expertise : string
}

class Report {
  + ReportId : int
  + Content : string
}

class CompensationDecision {
  + EligibleCosts : float
}

AlphaInsurance "1" -- "*" Customer
Broker "1" -- "*" Customer
Customer "1" -- "*" Contract
Customer "1" -- "*" ClaimCase
Contract "1" -- "1" Policy
Offer "1" -- "0..*" Customer
Offer "1" -- "1" Contract
Contract "1" -- "*" Invoice
ClaimCase "1" *-- "1..*" Report
Estimator "1" -- "*" Report
Report "1" -- "0..1" CompensationDecision
CompensationDecision "1" -- "1" ClaimCase

@enduml

